using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class InformationSchemeTests
{
 static readonly EntityId Agent=new("created:scheme-agent"),Writer=new("created:scheme-writer");
 internal static WorldSession Start(){var records=new[]{NewGameWorldTests.Officer("created:scheme-player"),NewGameWorldTests.Officer(Agent.Value),NewGameWorldTests.Officer(Writer.Value)};var setup=NewGameWorldTests.Setup(records);return new(NewGameWorld.Create(setup.World,setup.Registered,records[0].Id,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy));}
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static SchemeInput Input(WorldSession s,SchemeAction action,EntityId? person=null,EntityId? subject=null,EntityId? reference=null,EntityId? destination=null)=>new(new("request:scheme-test/"+s.Revision),action,person??Agent,subject??Writer,Reference:reference,Destination:destination);
 [Fact]public void HearsayReachesOnlyTheListenerAndDoesNotAlterLegalRelations(){var s=Start();var before=s.DiagnosticSnapshot();Good(s.ManageScheme(Input(s,SchemeAction.Whisper),s.Revision));var w=s.DiagnosticSnapshot();Assert.Empty(InformationSchemes.Claims(w,Writer));Assert.Single(InformationSchemes.Claims(w,Agent));Assert.Contains("未確認",InformationSchemes.Claims(w,Agent).Single().Standing);Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(w.Memberships));}
 [Fact]public void UnknownSourceCannotBeForwarded(){var s=Start();var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageScheme(Input(s,SchemeAction.Forward,reference:new("source:unknown")),s.Revision).Code);Assert.Equal(raw,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Theory][InlineData(false)][InlineData(true)]public void LetterNameIsUnknownUntilReceiptAndForgeryNeedsActualAuthorDenial(bool forged){var s=Start();var letter=Input(s,forged?SchemeAction.ForgeLetter:SchemeAction.WriteLetter,person:forged?Writer:s.PlayerControl);Good(s.ManageScheme(letter,s.Revision));Assert.Empty(InformationSchemes.Claims(s.DiagnosticSnapshot(),Agent));Good(s.ManageSocial(new(new("request:scheme-paper"),SocialWorldAction.DispatchGift,Agent){Asset=letter.Id},s.Revision));var w=s.DiagnosticSnapshot();var heard=Assert.Single(InformationSchemes.Claims(w,Agent));Assert.Equal(letter.Person,heard.Speaker);Assert.Equal("書状の記載。名義と真偽は未確認",heard.Standing);Assert.DoesNotContain("犯人",heard.Statement);w.CommitSequence++;var check=new SchemeInput(new("request:verify-paper"),SchemeAction.VerifyLetter,letter.Person,Writer,Reference:letter.Id);InformationSchemes.Execute(w,check,Agent);var result=InformationSchemes.Claims(w,Agent).Last();Assert.Equal(forged,result.Statement.Contains("否認"));Assert.Contains("未確定",result.Standing);w.CommitSequence++;InformationSchemes.Execute(w,new(new("request:relay-denial"),SchemeAction.ShowDenial,s.PlayerControl,Writer,Reference:check.Id),Agent);Assert.NotEmpty(InformationSchemes.Claims(w,s.PlayerControl));ContractValidation.Validate(w);}
 [Fact]public void TempleOnlySuppliesTheReputationItActuallyWitnessed(){var s=Start();var site=new EntityId("site:castle");var temple=SocialWorld.Temple(s.DiagnosticSnapshot(),site);Good(s.ManageSocial(new(new("request:temple-info-donation"),SocialWorldAction.Donate,temple.Representative,Amount:20),s.Revision));var w=s.DiagnosticSnapshot();w.CommitSequence++;InformationSchemes.Execute(w,new(new("request:temple-info"),SchemeAction.QueryTemple,temple.Representative,Agent),Agent);Assert.Contains(SocialWorld.Renown(w,Agent),f=>f.Subject==s.PlayerControl);Assert.Empty(SocialWorld.Renown(w,Writer));ContractValidation.Validate(w);}
 [Fact]public void ScoutMustBeConsentingAndPublicCannotInventTheReturn(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.ManageScheme(Input(s,SchemeAction.SendScout,destination:new("site:fork")),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageScheme(Input(s,SchemeAction.ReportScout),s.Revision).Code);}
 [Fact]public void RealScoutReturnsBeforeSealedInformationBecomesKnowledgeAndSaveRestores(){var s=Start();Good(s.ManageCompanion(new(new("request:scout-agree"),Agent,CompanionAction.Agree,20),s.PlayerControl,s.Revision));var input=Input(s,SchemeAction.SendScout,destination:RegionalCampaign.Site("fork"));Good(s.ManageScheme(input,s.Revision));var w=s.DiagnosticSnapshot();var move=w.Schemes!.Events.Single(e=>e.Input.Id==input.Id).Movement!;Assert.Contains(w.Requests,r=>r.Id==move.RequestId);NewGameWorldTests.At(s,move.EffectiveAt+move.DeliverySeconds+move.WorkSeconds);w=s.DiagnosticSnapshot();var capture=w.Schemes!.Events.Single(e=>e.Input.Action==SchemeAction.CaptureScout);Assert.NotEmpty(capture.Sources);Assert.DoesNotContain(w.Evidence,e=>e.Observer==s.PlayerControl&&e.Message?.Value==InformationSchemes.ReportId(input.Id));var back=w.Schemes.Events.Single(e=>e.Input.Action==SchemeAction.PlanReturn).Movement!;s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"scheme-scout-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"scout",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("scout"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current}){NewGameWorldTests.At(x,back.EffectiveAt+back.DeliverySeconds+back.WorkSeconds+2);var current=x.DiagnosticSnapshot();string report=InformationSchemes.ReportId(input.Id);Assert.DoesNotContain(current.Evidence,e=>e.Observer==x.PlayerControl&&e.Message?.Value==report);Good(x.Open(x.PlayerControl,new(report),x.Revision));Assert.Contains(x.DiagnosticSnapshot().Evidence,e=>e.Observer==x.PlayerControl&&e.Message?.Value==report);}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
 [Fact]public void OldSocialAssetsBytesStayUnchanged(){var s=Start();Good(s.ManageSocialAsset(new(new("request:before-schemes"),SocialAssetAction.Buy,s.PlayerControl,SocialAssets.Catalog(s.DiagnosticSnapshot(),new("site:castle"))[0].Id),s.Revision));var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Schemes",System.Text.Encoding.UTF8.GetString(raw));Assert.Equal(raw,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(raw)).DiagnosticSnapshot()));}
 [Fact]public void UnknownClosureIsOnlyKnownAfterTheActualReturnAndOpening(){var s=Start();Good(s.ManageCompanion(new(new("request:blocked-scout-agree"),Agent,CompanionAction.Agree,20),s.PlayerControl,s.Revision));var w=s.DiagnosticSnapshot();var edges=BranchRoutes.GraphEdges(w).Where(e=>e.From=="castle"||e.To=="castle").Select(e=>e.Id).ToArray();w.Couriers=w.Couriers! with{Conditions=edges.Select(edge=>new RoadCondition(1,edge,true)).ToArray()};s=new(w);var input=Input(s,SchemeAction.SendScout,destination:RegionalCampaign.Site("fork"));Good(s.ManageScheme(input,s.Revision));var trip=s.DiagnosticSnapshot().Schemes!.Events.Single(e=>e.Input.Id==input.Id).Movement!;NewGameWorldTests.At(s,trip.EffectiveAt+trip.DeliverySeconds+trip.WorkSeconds+5);Assert.DoesNotContain(BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),s.PlayerControl),edge=>edges.Contains(edge));var report=new EntityId(InformationSchemes.ReportId(input.Id));var opened=s.Open(s.PlayerControl,report,s.Revision);Assert.True(opened.Code==ResultCode.Accepted,opened.VisibleReason+" / "+System.Text.Json.JsonSerializer.Serialize(new{ s.Seconds,Events=s.DiagnosticSnapshot().Schemes!.Events.Select(e=>e.Input.Action.ToString()),Tasks=s.DiagnosticSnapshot().Tasks.Select(t=>new{t.Execution,t.InternalReason,t.FinishedAt}),Locations=s.DiagnosticSnapshot().Locations,Attempts=s.DiagnosticSnapshot().Messaging.Attempts}));Assert.Contains(BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),s.PlayerControl),edge=>edges.Contains(edge));}
 [Fact]public void NpcOnlyRelaysWhatItHeardAndClockPartitionDoesNotInventClaims(){var a=Start();Good(a.ManageScheme(Input(a,SchemeAction.Whisper,subject:a.PlayerControl),a.Revision));var b=new WorldSession(ContractJson.Copy(a.DiagnosticSnapshot()));NewGameWorldTests.At(a,86400);foreach(var time in new long[]{1,43200,86400})NewGameWorldTests.At(b,time);var x=InformationSchemes.Claims(a.DiagnosticSnapshot(),Writer);var y=InformationSchemes.Claims(b.DiagnosticSnapshot(),Writer);Assert.NotEmpty(x);Assert.Equal(ContractJson.Write(x),ContractJson.Write(y));}

 [Fact]public void NpcRecognizesItsOwnDisavowedAuthorshipWithoutLearningTheForger(){var s=Start();var input=Input(s,SchemeAction.ForgeLetter,person:Agent);Good(s.ManageScheme(input,s.Revision));Good(s.ManageSocial(new(new("request:to-claimed-writer"),SocialWorldAction.DispatchGift,Agent){Asset=input.Id},s.Revision));var claims=InformationSchemes.Claims(s.DiagnosticSnapshot(),Agent);Assert.Contains(claims,c=>c.Statement.Contains("否認"));Assert.All(claims,c=>Assert.DoesNotContain("作成者は",c.Statement));}

}
